import 'dart:convert';
import 'dart:io';

import 'package:flutter_test/flutter_test.dart';
import 'package:mars_terraforming/domain/game_content.dart';
import 'package:mars_terraforming/application/game_controller.dart';
import 'package:mars_terraforming/domain/save_repository.dart';
import 'package:mars_terraforming/infrastructure/file_save_store.dart';
import 'package:mars_terraforming/infrastructure/key_value_save_store.dart';

// Generated by the unmodified engine at 1a2d52c: a paid contract is 30 seconds
// into its first run, after the first landing and dome achievement were saved.
void main() {
  final legacy = jsonDecode(
    File('test/fixtures/prototype_v1.json').readAsStringSync(),
  ) as Map<String, dynamic>;
  final epoch = DateTime.fromMillisecondsSinceEpoch(
    legacy['lastWallClockMs'] as int,
    isUtc: true,
  );

  // Actual district-2 engine snapshot at ac8e9f9. A highland campus upgrade
  // has paid its former 4x cost/time, with solar construction queued behind it.
  final districtLegacy = jsonDecode(
    File('test/fixtures/district_v2.json').readAsStringSync(),
  ) as Map<String, dynamic>;
  final districtEpoch = DateTime.fromMillisecondsSinceEpoch(
    districtLegacy['lastWallClockMs'] as int,
    isUtc: true,
  );

  for (final native in [true, false]) {
    test(
      '${native ? 'file' : 'browser'} old save migrates without replaying paid work or awards',
      () async {
        final directory = await Directory.systemTemp.createTemp(
          'mars-migration-',
        );
        addTearDown(() => directory.delete(recursive: true));
        final storage = <String, String>{};
        SaveRepository reopen() => native
            ? FileSaveStore(directory)
            : KeyValueSaveStore(
                read: (key) => storage[key],
                write: (key, value) => storage[key] = value,
              );
        await reopen().save(legacy);
        final controller = GameController(reopen(), now: () => epoch);
        await controller.initialize(startTimer: false);
        expect(controller.error, isNull);
        expect(controller.state.worldId, legacy['worldId']);
        expect(controller.state.moneyUnits, legacy['moneyUnits']);
        expect(controller.state.marsResidents, 12);
        expect(controller.state.claimedRewards, legacy['claimedRewards']);
        expect(controller.state.currentPlanFor('factory')!.remainingMs, 60000);
        expect(controller.state.contractRevenue, 0);
        final migrated = controller.state.toJson();
        expect(migrated['schemaVersion'], 2);
        expect((await reopen().load()).data, migrated);
        controller.dispose();

        final again = GameController(reopen(), now: () => epoch);
        await again.initialize(startTimer: false);
        expect(again.state.toJson(), migrated);
        again.dispose();

        final finished = GameController(
          reopen(),
          now: () => epoch.add(const Duration(seconds: 60)),
        );
        await finished.initialize(startTimer: false);
        expect(finished.state.contractRevenue, 220);
        expect(finished.state.plans.last.completedRuns, 1);
        expect(finished.state.claimedRewards, legacy['claimedRewards']);
        final afterCompletion = finished.state.toJson();
        finished.dispose();
        final afterReload = GameController(
          reopen(),
          now: () => epoch.add(const Duration(seconds: 60)),
        );
        addTearDown(afterReload.dispose);
        await afterReload.initialize(startTimer: false);
        expect(afterReload.state.toJson(), afterCompletion);
      },
    );
  }
  for (final native in [true, false]) {
    test(
      '${native ? 'file' : 'browser'} district-2 preserves its paid upgrade and adopts future prices',
      () async {
        final directory = await Directory.systemTemp.createTemp(
          'mars-investment-migration-',
        );
        addTearDown(() => directory.delete(recursive: true));
        final storage = <String, String>{};
        SaveRepository reopen() => native
            ? FileSaveStore(directory)
            : KeyValueSaveStore(
                read: (key) => storage[key],
                write: (key, value) => storage[key] = value,
              );
        await reopen().save(districtLegacy);
        final controller = GameController(reopen(), now: () => districtEpoch);
        await controller.initialize(startTimer: false);
        addTearDown(controller.dispose);
        expect(controller.error, isNull);
        expect(controller.state.moneyUnits, districtLegacy['moneyUnits']);
        expect(controller.state.research, districtLegacy['research']);
        final original = (districtLegacy['plans'] as List)
            .cast<Map<String, dynamic>>()
            .firstWhere((p) => p['taskId'] == 'upgrade_campus');
        final paid = controller.state.currentPlanFor('factory')!;
        expect(paid.remainingMs, original['remainingMs']);
        expect(paid.iterationDurationMs, original['iterationDurationMs']);
        expect(
          paid.iterationDurationMs,
          greaterThan(controller.state.plannedDurationMs(paid)),
        );
        expect(
          controller.state.cityDevelopment('earth_highland').completedPlots,
          2,
        );
        final solar = controller.state.plans.firstWhere(
          (p) => p.taskId == 'district_solar',
        );
        expect(
          controller.state.plannedCost(solar),
          806,
        ); // Existing city, 2 plots: no opening fee.
        expect(
          controller.state.toJson()['contentVersion'],
          GameContent.version,
        );
        await controller.command((game) {
          final contract = game.state.plans.firstWhere(
            (p) => p.taskId == 'factory_contract',
          );
          expect(game.cancelQueued(contract.id), isNull);
          game.advanceBy(Duration(milliseconds: paid.remainingMs));
          expect(solar.requiresManualStart, isTrue);
          return game.startPlan(solar.id);
        });
        expect(controller.state.districtAt('earth_highland', 0)!.level, 2);
        expect(paid.completedRuns, 1);
        expect(solar.status, 'running');
        final after = controller.state.toJson();
        final resumed = GameController(reopen(), now: () => districtEpoch);
        addTearDown(resumed.dispose);
        await resumed.initialize(startTimer: false);
        expect(resumed.state.toJson(), after);
        expect(resumed.state.currentPlanFor('factory')!.id, solar.id);
      },
    );
  }
  // Actual district-3 engine at 9808084: a 1,500 Cr / 12 minute industry
  // construction is already paid; a second industry plot is still queued.
  final thirdLegacy = jsonDecode(
    File('test/fixtures/district_v3.json').readAsStringSync(),
  ) as Map<String, dynamic>;
  final thirdEpoch = DateTime.fromMillisecondsSinceEpoch(
    thirdLegacy['lastWallClockMs'] as int,
    isUtc: true,
  );
  for (final native in [true, false]) {
    test(
      '${native ? 'file' : 'browser'} district-3 retains paid industry and reprices only future work',
      () async {
        final directory = await Directory.systemTemp.createTemp(
          'mars-district3-',
        );
        addTearDown(() => directory.delete(recursive: true));
        final storage = <String, String>{};
        SaveRepository reopen() => native
            ? FileSaveStore(directory)
            : KeyValueSaveStore(
                read: (key) => storage[key],
                write: (key, value) => storage[key] = value,
              );
        await reopen().save(thirdLegacy);
        final controller = GameController(reopen(), now: () => thirdEpoch);
        await controller.initialize(startTimer: false);
        addTearDown(controller.dispose);
        expect(controller.error, isNull);
        expect(controller.state.moneyUnits, thirdLegacy['moneyUnits']);
        final paid = controller.state.currentPlanFor('factory')!;
        expect(
          paid.iterationDurationMs,
          const Duration(minutes: 12).inMilliseconds,
        );
        expect(
          paid.remainingMs,
          const Duration(minutes: 11, seconds: 30).inMilliseconds,
        );
        final queued = controller.state.plans.last;
        expect(queued.status, 'queued');
        expect(controller.state.plannedCost(queued), 1200);
        expect(
          controller.state.toJson()['contentVersion'],
          GameContent.version,
        );
        await controller.command((game) {
          game.advanceBy(Duration(milliseconds: paid.remainingMs));
          return null;
        });
        expect(paid.completedRuns, 1);
        expect(queued.status, 'queued');
        expect(queued.requiresManualStart, isTrue);
        await controller.command((game) => game.startPlan(queued.id));
        expect(queued.status, 'running');
        expect(
          queued.iterationDurationMs,
          lessThan(const Duration(minutes: 9).inMilliseconds),
        );
        // Completion introduced city congestion: new base 1,200 * 112%.
        expect(controller.state.plannedCost(queued), 1344);
        final after = controller.state.toJson();
        final resumed = GameController(reopen(), now: () => thirdEpoch);
        addTearDown(resumed.dispose);
        await resumed.initialize(startTimer: false);
        expect(resumed.state.toJson(), after);
        await resumed.command((game) {
          game.advanceBy(Duration(milliseconds: queued.remainingMs));
          return null;
        });
        expect(resumed.state.districts.length, 2);
        expect(resumed.state.plans.every((p) => p.completedRuns == 1), isTrue);
        final completed = resumed.state.toJson();
        final again = GameController(reopen(), now: () => thirdEpoch);
        addTearDown(again.dispose);
        await again.initialize(startTimer: false);
        expect(again.state.toJson(), completed);
      },
    );
  }
  // Actual pre-agency world: both departments have already paid for work.
  final fourthLegacy = jsonDecode(
    File('test/fixtures/district_v4.json').readAsStringSync(),
  ) as Map<String, dynamic>;
  final fourthEpoch = DateTime.fromMillisecondsSinceEpoch(
    fourthLegacy['lastWallClockMs'] as int,
    isUtc: true,
  );
  for (final native in [true, false]) {
    test(
      '${native ? 'file' : 'browser'} district-4 keeps legacy records while future work needs no staffing',
      () async {
        final directory = await Directory.systemTemp.createTemp(
          'mars-agency-migration-',
        );
        addTearDown(() => directory.delete(recursive: true));
        final storage = <String, String>{};
        SaveRepository reopen() => native
            ? FileSaveStore(directory)
            : KeyValueSaveStore(
                read: (key) => storage[key],
                write: (key, value) => storage[key] = value,
              );
        await reopen().save(fourthLegacy);
        final controller = GameController(reopen(), now: () => fourthEpoch);
        await controller.initialize(startTimer: false);
        addTearDown(controller.dispose);
        expect(controller.error, isNull);
        expect(controller.state.moneyUnits, fourthLegacy['moneyUnits']);
        expect(controller.state.specialistCount, 12);
        expect(controller.state.researchers, 6);
        expect(controller.state.industrialWorkers, 6);
        expect(controller.state.reservedResearchers, 6);
        expect(controller.state.reservedIndustrialWorkers, 6);
        expect(controller.state.partnershipChoices, isEmpty);
        expect(
          controller.state.currentPlanFor('lab')!.iterationDurationMs,
          120000,
        );
        expect(controller.state.currentPlanFor('lab')!.remainingMs, 90000);
        expect(
          controller.state.currentPlanFor('factory')!.iterationDurationMs,
          90000,
        );
        expect(controller.state.currentPlanFor('factory')!.remainingMs, 60000);
        final original = controller.state.toJson();
        await controller.command((game) => game.assignResearchers(8));
        expect(controller.state.toJson(), original);
        await controller.command((game) {
          game.advanceBy(const Duration(seconds: 90));
          return null;
        });
        expect(controller.state.reservedResearchers, 0);
        expect(controller.state.reservedIndustrialWorkers, 0);
        expect(controller.state.research, contains('life_support'));
        await controller.command((game) => game.assignResearchers(4));
        expect(controller.state.researchers, 6);
        expect(controller.state.industrialWorkers, 6);
        expect(
          controller.state.currentPlanFor('factory')!.iterationSpecialists,
          0,
        );
        expect(
          controller.state.currentPlanFor('factory')!.iterationDurationMs,
          90000,
        );
        final before = controller.state.toJson();
        final resumed = GameController(reopen(), now: () => fourthEpoch);
        addTearDown(resumed.dispose);
        await resumed.initialize(startTimer: false);
        expect(resumed.state.toJson(), before);
        expect(resumed.state.partnershipChoices, isEmpty);
        await resumed.command((game) {
          game.advanceBy(const Duration(seconds: 60));
          return null;
        });
        expect(
          resumed.state.currentPlanFor('factory')!.iterationSpecialists,
          0,
        );
        expect(
          resumed.state.currentPlanFor('factory')!.iterationDurationMs,
          90000,
        );
        final next = resumed.state.toJson();
        final again = GameController(reopen(), now: () => fourthEpoch);
        addTearDown(again.dispose);
        await again.initialize(startTimer: false);
        expect(again.state.toJson(), next);
      },
    );
  }
}
